/// <summary>
/// Where the account's half stands.
/// </summary>
public enum AccountBillingState: int {
    /// <summary>
    /// Being read.
    /// </summary>
    Loading,
    /// <summary>
    /// Read.
    /// </summary>
    Ready,
    /// <summary>
    /// The payment processor could not be reached: never shown as "none".
    /// </summary>
    Unavailable,
    /// <summary>
    /// The read failed.
    /// </summary>
    Failed
}

class FfiConverterTypeAccountBillingState: FfiConverterRustBuffer<AccountBillingState> {
    public static FfiConverterTypeAccountBillingState INSTANCE = new FfiConverterTypeAccountBillingState();

    public override AccountBillingState Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return AccountBillingState.Loading;
            case 2: return AccountBillingState.Ready;
            case 3: return AccountBillingState.Unavailable;
            case 4: return AccountBillingState.Failed;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAccountBillingState.Read()", value));
        }
    }

    public override int AllocationSize(AccountBillingState value) {
        return 4;
    }

    public override void Write(AccountBillingState value, BigEndianStream stream) {
        switch (value) {
            case AccountBillingState.Loading: stream.WriteInt(1); break;
            case AccountBillingState.Ready: stream.WriteInt(2); break;
            case AccountBillingState.Unavailable: stream.WriteInt(3); break;
            case AccountBillingState.Failed: stream.WriteInt(4); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAccountBillingState.Write()", value));
        }
    }
}







/// <summary>
/// Something the member did on the analytics screen.
/// </summary>
public record AnalyticsAction {
    
    /// <summary>
    /// Open the analytics.
    /// </summary>
    public record Open: AnalyticsAction {}
    
    
    /// <summary>
    /// Show the figures for `period`. Picking the period selected does nothing.
    /// </summary>
    public record SelectPeriod (
        AnalyticsPeriod Period
    ) : AnalyticsAction {}
    
    /// <summary>
    /// Read everything again: Try again, after a failure.
    /// </summary>
    public record Retry: AnalyticsAction {}
    
    

    
}

class FfiConverterTypeAnalyticsAction : FfiConverterRustBuffer<AnalyticsAction>{
    public static FfiConverterRustBuffer<AnalyticsAction> INSTANCE = new FfiConverterTypeAnalyticsAction();

    public override AnalyticsAction Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new AnalyticsAction.Open(
                );
            case 2:
                return new AnalyticsAction.SelectPeriod(
                    FfiConverterTypeAnalyticsPeriod.INSTANCE.Read(stream)
                );
            case 3:
                return new AnalyticsAction.Retry(
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAnalyticsAction.Read()", value));
        }
    }

    public override int AllocationSize(AnalyticsAction value) {
        switch (value) {
            case AnalyticsAction.Open variant_value:
                return 4;
            case AnalyticsAction.SelectPeriod variant_value:
                return 4
                    + FfiConverterTypeAnalyticsPeriod.INSTANCE.AllocationSize(variant_value.Period);
            case AnalyticsAction.Retry variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAnalyticsAction.AllocationSize()", value));
        }
    }

    public override void Write(AnalyticsAction value, BigEndianStream stream) {
        switch (value) {
            case AnalyticsAction.Open variant_value:
                stream.WriteInt(1);
                break;
            case AnalyticsAction.SelectPeriod variant_value:
                stream.WriteInt(2);
                FfiConverterTypeAnalyticsPeriod.INSTANCE.Write(variant_value.Period, stream);
                break;
            case AnalyticsAction.Retry variant_value:
                stream.WriteInt(3);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAnalyticsAction.Write()", value));
        }
    }
}







