    /// </summary>
    Gif,
    /// <summary>
    /// WebP: `RIFF`, four bytes of length, `WEBP`.
    /// </summary>
    Webp,
    /// <summary>
    /// HEIC: an ISO box `ftyp` whose major brand is one of HEVC-coded
    /// images' (`heic`, `heix`, `hevc`, `hevx`, `heim`, `heis`, `hevm`,
    /// `hevs`). The service takes none, and the core says so.
    /// </summary>
