/// <summary>
/// The report this session started, while it is under way or until its outcome
/// is dismissed.
/// </summary>
public record ReportStatus {
    
    /// <summary>
    /// On its way.
    /// </summary>
    public record Sending: ReportStatus {}
    
    
    /// <summary>
    /// Raised.
    /// </summary>
    public record Sent (
        string Message
    ) : ReportStatus {}
    
    /// <summary>
    /// Not raised.
    /// </summary>
    public record Failed (
        string Message
    ) : ReportStatus {}
    

    
}

class FfiConverterTypeReportStatus : FfiConverterRustBuffer<ReportStatus>{
    public static FfiConverterRustBuffer<ReportStatus> INSTANCE = new FfiConverterTypeReportStatus();

    public override ReportStatus Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ReportStatus.Sending(
                );
            case 2:
                return new ReportStatus.Sent(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 3:
                return new ReportStatus.Failed(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeReportStatus.Read()", value));
        }
    }

    public override int AllocationSize(ReportStatus value) {
        switch (value) {
            case ReportStatus.Sending variant_value:
                return 4;
            case ReportStatus.Sent variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Message);
            case ReportStatus.Failed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Message);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeReportStatus.AllocationSize()", value));
        }
    }

    public override void Write(ReportStatus value, BigEndianStream stream) {
        switch (value) {
            case ReportStatus.Sending variant_value:
                stream.WriteInt(1);
                break;
            case ReportStatus.Sent variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.Message, stream);
                break;
            case ReportStatus.Failed variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.Message, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeReportStatus.Write()", value));
        }
    }
}







/// <summary>
/// What a report is about. Only its kind and id reach the support desk, never
/// the content itself.
/// </summary>
public record ReportTarget {
    
    /// <summary>
    /// A call's AI summary.
    /// </summary>
    public record Call (
        string CallId
    ) : ReportTarget {}
    
    /// <summary>
    /// A contact's AI dossier.
    /// </summary>
    public record Contact (
        string ContactId
    ) : ReportTarget {}
    
    /// <summary>
    /// A call's AI summary in a conversation's timeline.
    /// </summary>
    public record ThreadEvent (
        string ThreadKey,
        string EventId
    ) : ReportTarget {}
    
    /// <summary>
    /// A reply the model wrote into a conversation's reply box. The service
    /// gives a written reply no id, so the report names its kind and the
    /// conversation's contact, and the member's note says the rest.
    /// </summary>
    public record AiDraft (
        string ThreadKey
    ) : ReportTarget {}
    
    /// <summary>
    /// An answer District HQ gave. The service keeps no conversation and gives
    /// an answer no id, so the report names its kind, and the member's note
    /// says the rest.
    /// </summary>
    public record HqAnswer: ReportTarget {}
    
    

    
}

class FfiConverterTypeReportTarget : FfiConverterRustBuffer<ReportTarget>{
    public static FfiConverterRustBuffer<ReportTarget> INSTANCE = new FfiConverterTypeReportTarget();

    public override ReportTarget Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ReportTarget.Call(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 2:
                return new ReportTarget.Contact(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 3:
                return new ReportTarget.ThreadEvent(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 4:
                return new ReportTarget.AiDraft(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 5:
                return new ReportTarget.HqAnswer(
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeReportTarget.Read()", value));
        }
    }

    public override int AllocationSize(ReportTarget value) {
        switch (value) {
            case ReportTarget.Call variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.CallId);
            case ReportTarget.Contact variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.ContactId);
            case ReportTarget.ThreadEvent variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.ThreadKey)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.EventId);
            case ReportTarget.AiDraft variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.ThreadKey);
            case ReportTarget.HqAnswer variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeReportTarget.AllocationSize()", value));
        }
    }

    public override void Write(ReportTarget value, BigEndianStream stream) {
        switch (value) {
            case ReportTarget.Call variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.CallId, stream);
                break;
            case ReportTarget.Contact variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.ContactId, stream);
                break;
            case ReportTarget.ThreadEvent variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.ThreadKey, stream);
                FfiConverterString.INSTANCE.Write(variant_value.EventId, stream);
                break;
            case ReportTarget.AiDraft variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.ThreadKey, stream);
                break;
            case ReportTarget.HqAnswer variant_value:
                stream.WriteInt(5);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeReportTarget.Write()", value));
        }
    }
}







/// <summary>
/// One block of rich text. Consecutive list items sit on lines of their own
/// with no gap between them; every other block has a gap before it.
/// </summary>
public record RichBlock {
    
    /// <summary>
    /// A paragraph. A line break inside it is a `\n` in a run's text.
    /// </summary>
    public record Paragraph (
        RichRun[] Runs
    ) : RichBlock {}
    
    /// <summary>
    /// A heading, of any level: shown as a strong line.
    /// </summary>
    public record Heading (
        RichRun[] Runs
    ) : RichBlock {}
    
    /// <summary>
    /// An item of a bulleted or numbered list.
    /// </summary>
    public record ListItem (
        string Marker,
        uint Depth,
        RichRun[] Runs
    ) : RichBlock {}
    
    /// <summary>
    /// A code block, shown as it is in a fixed-width font.
    /// </summary>
    public record Code (
        string Text
    ) : RichBlock {}
    

    
}

class FfiConverterTypeRichBlock : FfiConverterRustBuffer<RichBlock>{
    public static FfiConverterRustBuffer<RichBlock> INSTANCE = new FfiConverterTypeRichBlock();

    public override RichBlock Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new RichBlock.Paragraph(
                    FfiConverterSequenceTypeRichRun.INSTANCE.Read(stream)
                );
            case 2:
                return new RichBlock.Heading(
                    FfiConverterSequenceTypeRichRun.INSTANCE.Read(stream)
                );
            case 3:
                return new RichBlock.ListItem(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterSequenceTypeRichRun.INSTANCE.Read(stream)
                );
            case 4:
                return new RichBlock.Code(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRichBlock.Read()", value));
        }
    }

    public override int AllocationSize(RichBlock value) {
        switch (value) {
            case RichBlock.Paragraph variant_value:
                return 4
                    + FfiConverterSequenceTypeRichRun.INSTANCE.AllocationSize(variant_value.Runs);
            case RichBlock.Heading variant_value:
                return 4
                    + FfiConverterSequenceTypeRichRun.INSTANCE.AllocationSize(variant_value.Runs);
            case RichBlock.ListItem variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Marker)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Depth)
                    + FfiConverterSequenceTypeRichRun.INSTANCE.AllocationSize(variant_value.Runs);
            case RichBlock.Code variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Text);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRichBlock.AllocationSize()", value));
        }
    }

    public override void Write(RichBlock value, BigEndianStream stream) {
        switch (value) {
            case RichBlock.Paragraph variant_value:
                stream.WriteInt(1);
                FfiConverterSequenceTypeRichRun.INSTANCE.Write(variant_value.Runs, stream);
                break;
            case RichBlock.Heading variant_value:
                stream.WriteInt(2);
                FfiConverterSequenceTypeRichRun.INSTANCE.Write(variant_value.Runs, stream);
                break;
            case RichBlock.ListItem variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.Marker, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Depth, stream);
                FfiConverterSequenceTypeRichRun.INSTANCE.Write(variant_value.Runs, stream);
                break;
            case RichBlock.Code variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.Text, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRichBlock.Write()", value));
        }
    }
}







