    ) : UiEvent {}
    
    /// <summary>
    /// Something done on the phone numbers.
    /// </summary>
    public record Marketplace (
        MarketplaceAction Action
    ) : UiEvent {}
    
    /// <summary>
    /// Something done on billing.
