    public record Billing (
        BillingAction Action
    ) : UiEvent {}
    
    /// <summary>
    /// Something done on the workflows.
    /// </summary>
    public record Workflows (
        WorkflowsAction Action
    ) : UiEvent {}
    
    /// <summary>
    /// Something done on the booking pages.
    /// </summary>
    public record Scheduling (
        SchedulingAction Action
    ) : UiEvent {}
    
    /// <summary>
